using System.Text;
using System.Text.Json;

namespace NomadNet.Tests;

// Generated by executing pinned f6b56044b42f6ca08dc99b3ecb9d965a8eb5edb2.
// GenerateNomadNetTerminalControlVectors.py records actual Git-blob SHA256 and headless observers.
[Trait("Category", "Unit")]
public sealed class NomadNetTerminalControlTests
{
    private static JsonDocument Reference() => JsonDocument.Parse(typeof(NomadNetTerminalControlTests).Assembly
        .GetManifestResourceStream("NomadNet.Tests.NomadNetTerminalControlVectors.json")!);

    [Fact, Trait("TestId", "T540")]
    public void T540ExecutedPrimaryFieldsHaveRuntimeDispositionsAndExactDefaults()
    {
        using var reference = Reference();
        Assert.Equal("f6b56044b42f6ca08dc99b3ecb9d965a8eb5edb2", reference.RootElement.GetProperty("revision").GetString());
        foreach (var item in reference.RootElement.GetProperty("fields").EnumerateArray())
        {
            var field = Assert.Single(NomadNetConfigurationFields.All, f => f.Key == item.GetProperty("key").GetString() &&
                f.Section is "textui" or "utilities");
            Assert.Equal("runtime", field.Disposition);
            Assert.Equal(item.GetProperty("type").GetString(), field.Type);
            var value = item.GetProperty("default");
            var expected = value.ValueKind == JsonValueKind.True ? "yes" : value.ValueKind == JsonValueKind.False ? "no" : value.GetString();
            Assert.Equal(expected, field.Default);
        }
    }

    [Fact, Trait("TestId", "T541")]
    public void T541ExecutedPrimaryNameVectorsMatchSanitationAndSafeOptOut()
    {
        using var reference = Reference();
        foreach (var item in reference.RootElement.GetProperty("names").EnumerateArray())
        {
            var input = item.GetProperty("input").GetString()!;
            Assert.Equal(item.GetProperty("sanitized").GetString(), NomadNetTerminalControls.Name(input, true));
            var upstream = item.GetProperty("modifiers").GetString()!;
            var safe = new StringBuilder();
            foreach (var rune in upstream.EnumerateRunes())
                if (!Rune.IsControl(rune) && rune.Value is not (0x2028 or 0x2029)) safe.Append(rune.ToString());
            Assert.Equal(safe.ToString().Trim(), NomadNetTerminalControls.Name(input, false));
        }
        Assert.Throws<InvalidDataException>(() => NomadNetTerminalControls.Name(new string('x', 65537), true));
        Assert.Throws<ArgumentNullException>(() => NomadNetTerminalControls.Name(null!, true));
    }

    [Fact, Trait("TestId", "T542")]
    public void T542ExecutedPrimaryMenusSeparateVisibilityFromExplicitGuideAndUtilityCommands()
    {
        using var reference = Reference();
        foreach (var row in reference.RootElement.GetProperty("menus").EnumerateArray())
        {
            var settings = new NomadNetSettings { EnableUtilities = row.GetProperty("utilities").GetBoolean(),
                HideGuide = row.GetProperty("hideGuide").GetBoolean() };
            var labels = row.GetProperty("labels").EnumerateArray().Select(v => v.GetString()).ToArray();
            Assert.Equal(labels.Contains("Utilities"), NomadNetTerminalControls.Menu(settings).Any(e => e.Label == "Utilities"));
            Assert.Equal(labels.Contains("Guide"), NomadNetTerminalControls.Menu(settings).Any(e => e.Label == "Guide"));
            Assert.Equal(settings.EnableUtilities, row.GetProperty("utilityConstructed").GetBoolean());
            Assert.Equal(3, row.GetProperty("announceTimeout").GetInt32());
        }
    }

    [Fact, Trait("TestId", "T543")]
    public void T543EveryNativeModeSelectsBoundedAnsiOrMonochromeWithoutColorLeaks()
    {
        using var reference = Reference();
        foreach (var row in reference.RootElement.GetProperty("terminal").EnumerateArray())
        {
            Assert.True(row.GetProperty("paletteMatchesSelectedTheme").GetBoolean());
            Assert.Equal(row.GetProperty("glyphs").GetString() != "plain", row.GetProperty("mouse").GetBoolean());
            if (row.GetProperty("intro").GetDouble() <= 0) Assert.Equal(JsonValueKind.Null, row.GetProperty("introAlarm").ValueKind);
            else
            {
                Assert.Equal(.125, row.GetProperty("introAlarm").GetDouble());
                Assert.Equal("Synthetic title", row.GetProperty("introText").GetString());
            }
        }
        foreach (var mode in new[] { "monochrome", "16", "88", "256", "24bit" })
        {
            var settings = new NomadNetSettings { ColorMode = mode };
            var value = NomadNetTerminalControls.Heading("original title", settings, true);
            Assert.Contains("original title", value);
            Assert.Equal("original title", NomadNetTerminalControls.Heading("original title", settings, false));
            if (mode == "monochrome") Assert.Equal("original title", value);
            else Assert.EndsWith("\u001b[0m", value);
            if (mode == "24bit") Assert.Contains("38;2;", value);
            if (mode is "88" or "256") Assert.Contains("38;5;", value);
            if (mode == "16") { Assert.DoesNotContain("38;", value); Assert.Contains("\u001b[1;3", value); }
        }
        Assert.Throws<FormatException>(() => NomadNetTerminalControls.Color("x", "bad", new(), true));
        Assert.Throws<ArgumentException>(() => NomadNetTerminalControls.Color("x", "1234", new(), true));
    }

    [Fact, Trait("TestId", "T544")]
    public void T544ThemeAndGlyphControlsAlterOriginalRenderedMenuNotData()
    {
        var dark = new NomadNetSettings();
        var light = dark with { Theme = "light" };
        Assert.NotEqual(NomadNetTerminalControls.Heading("same", dark, true), NomadNetTerminalControls.Heading("same", light, true));
        var menus = new[] { "plain", "unicode", "nerdfont" }.Select(g => NomadNetTerminalControls.MenuText(dark with { Glyphs = g })).ToArray();
        Assert.Equal(3, menus.Distinct().Count());
        Assert.All(menus, m => Assert.Contains("Conversations", m));
        Assert.StartsWith("* ", menus[0]);
    }

    [Fact, Trait("TestId", "T545")]
    public void T545MouseSelectsOnlyEnabledVisibleMenuOnPrimaryButtonDown()
    {
        var settings = new NomadNetSettings();
        Assert.Equal("conversations", NomadNetTerminalControls.Mouse(settings, "\u001b[<0;4;1M"));
        Assert.Null(NomadNetTerminalControls.Mouse(settings with { MouseEnabled = false }, "\u001b[<0;4;1M"));
        foreach (var input in new[] { "", "\u001b[<0;4;1m", "\u001b[<1;4;1M", "\u001b[<64;4;1M",
            "\u001b[<0;4;2M", "\u001b[<0;-4;1M", "\u001b[<0;999999999999;1M", "\u001b[<0;4097;1M",
            "\u001b[<0;4;1;2M", new string('x', 33), "\u001b[<0;1;1M" })
            Assert.Null(NomadNetTerminalControls.Mouse(settings, input));
        Assert.Throws<ArgumentOutOfRangeException>(() => NomadNetTerminalControls.Select(settings, 0));
        Assert.Throws<ArgumentOutOfRangeException>(() => NomadNetTerminalControls.Select(settings, 99));
        Assert.Equal("quit", NomadNetTerminalControls.Select(settings, NomadNetTerminalControls.Menu(settings).Count));
    }

    [Fact, Trait("TestId", "T546")]
    public void T546PrimaryProjectionExportRoundTripsAllTenControlsAndPreservesUnknownLists()
    {
        using var reference = Reference();
        foreach (var row in reference.RootElement.GetProperty("loader").EnumerateArray())
        {
            var input = row.GetProperty("input").GetString()!;
            var name = row.GetProperty("name").GetString();
            if (name == "missing-colormode")
            {
                Assert.Equal("AttributeError", row.GetProperty("observed").GetProperty("error").GetString());
                Assert.Equal("24bit", NomadNetConfigImport.Parse(input).Settings.ColorMode); // Explicit native bug-avoidance default.
            }
            else if (name is "zero-animation" or "invalid-theme")
                Assert.Throws<InvalidDataException>(() => NomadNetConfigImport.Parse(input));
            else
            {
                var observed = row.GetProperty("observed");
                var text = observed.GetProperty("textui");
                var settings = NomadNetConfigImport.Parse(input).Settings;
                Assert.Equal(text.GetProperty("intro_time").GetDouble(), settings.IntroTime);
                Assert.Equal(text.GetProperty("intro_text").GetString(), settings.IntroText);
                Assert.Equal(text.GetProperty("theme").GetInt32() == 1 ? "dark" : "light", settings.Theme);
                Assert.Equal(text.GetProperty("colormode").GetInt32().ToString(), settings.ColorMode);
                Assert.Equal(text.GetProperty("glyphs").GetString(), settings.Glyphs);
                Assert.Equal(text.GetProperty("mouse_enabled").GetBoolean(), settings.MouseEnabled);
                Assert.Equal(text.GetProperty("hide_guide").GetBoolean(), settings.HideGuide);
                Assert.Equal(text.GetProperty("sanitize_names").GetBoolean(), settings.SanitizeNames);
                Assert.Equal(text.GetProperty("animation_interval").GetInt32(), settings.AnimationInterval);
                Assert.Equal(observed.GetProperty("utilities").GetProperty("enable_utilities").GetBoolean(), settings.EnableUtilities);
            }
        }
        var expected = new NomadNetSettings { IntroTime = .125, IntroText = "Original custom title", Theme = "light",
            ColorMode = "88", Glyphs = "plain", MouseEnabled = false, HideGuide = true, SanitizeNames = false,
            AnimationInterval = 3, EnableUtilities = true, NodePageRefreshIntervalMinutes = 0, NodeFileRefreshIntervalMinutes = 0 };
        var parsed = NomadNetConfigImport.Overlay(NomadNetPrimaryConfiguration.Export(expected) +
            "\n[future]\nlist = one, two\n", new());
        var result = parsed.Settings;
        Assert.Equal(expected.IntroTime, result.IntroTime);
        Assert.Equal(expected.IntroText, result.IntroText);
        Assert.Equal(expected.Theme, result.Theme);
        Assert.Equal(expected.ColorMode, result.ColorMode);
        Assert.Equal(expected.Glyphs, result.Glyphs);
        Assert.Equal(expected.MouseEnabled, result.MouseEnabled);
        Assert.Equal(expected.HideGuide, result.HideGuide);
        Assert.Equal(expected.SanitizeNames, result.SanitizeNames);
        Assert.Equal(expected.AnimationInterval, result.AnimationInterval);
        Assert.Equal(expected.EnableUtilities, result.EnableUtilities);
        Assert.Equal(["future.list"], parsed.UnsupportedKeys);
        Assert.Equal("unicode", NomadNetConfigImport.Parse("[textui]\nglyphs=invalid\n").Settings.Glyphs);
    }

    [Fact, Trait("TestId", "T547")]
    public void T547MalformedAndUnboundedNativeOrPrimaryControlsAreRejected()
    {
        foreach (var settings in new[] { new NomadNetSettings { IntroTime = double.NaN },
            new() { IntroTime = double.PositiveInfinity }, new() { IntroTime = 61 }, new() { IntroTime = -3601 },
            new() { IntroText = new string('x', 257) }, new() { IntroText = "bad\u001b" },
            new() { IntroText = null! }, new() { AnimationInterval = 0 }, new() { AnimationInterval = 3601 },
            new() { Theme = "invalid" }, new() { ColorMode = "8" }, new() { Glyphs = "invalid" } })
            Assert.Throws<InvalidDataException>(() => NomadNetTerminalControls.Validate(settings));
        foreach (var text in new[] { "intro_time=nan", "intro_time=invalid", "intro_time=61", "animation_interval=0",
            "animation_interval=1.5", "mouse_enabled=maybe", "colormode=invalid", "theme=invalid" })
            Assert.Throws<InvalidDataException>(() => NomadNetConfigImport.Parse("[textui]\n" + text));
        NomadNetTerminalControls.Validate(new() { IntroTime = -3600, IntroText = "", AnimationInterval = 3600 });
        NomadNetTerminalControls.Validate(new() { IntroTime = 60, IntroText = new string('x', 256) });
    }

    [Fact, Trait("TestId", "T548")]
    public async Task T548IntroDisabledOrCancelledDoesNotWaitOrWriteAndFailuresPropagate()
    {
        var output = new StringWriter();
        await NomadNetTerminalControls.IntroAsync(new() { IntroTime = 0 }, output, false, default);
        await NomadNetTerminalControls.IntroAsync(new() { IntroTime = -1 }, output, false, default);
        Assert.Equal("", output.ToString());
        using var cancel = new CancellationTokenSource();
        cancel.Cancel();
        await Assert.ThrowsAnyAsync<OperationCanceledException>(() =>
            NomadNetTerminalControls.IntroAsync(new(), output, false, cancel.Token));
        Assert.Equal("", output.ToString());
        await Assert.ThrowsAsync<IOException>(() => NomadNetTerminalControls.IntroAsync(new(), new FailedWriter(), false, default));
    }

    [Fact, Trait("TestId", "T549")]
    public async Task T549WatchValidatesBoundsCancellationAndCoreWithoutObserver()
    {
        var output = new StringWriter();
        var called = 0;
        await NomadNetTerminalControls.WatchAsync(new(), 1, () => { called++; return "network ready"; }, output, false, default);
        Assert.Equal(1, called);
        Assert.Contains("network ready", output.ToString());
        Assert.DoesNotContain('\u001b', output.ToString());
        foreach (var frames in new[] { 0, 61 })
            await Assert.ThrowsAsync<ArgumentOutOfRangeException>(() =>
                NomadNetTerminalControls.WatchAsync(new(), frames, () => "", output, false, default));
        using var cancel = new CancellationTokenSource();
        cancel.Cancel();
        await Assert.ThrowsAnyAsync<OperationCanceledException>(() =>
            NomadNetTerminalControls.WatchAsync(new(), 2, () => "", output, false, cancel.Token));
        await Assert.ThrowsAsync<IOException>(() =>
            NomadNetTerminalControls.WatchAsync(new(), 1, () => "ready", new FailedWriter(), false, default));
    }

    [Fact, Trait("TestId", "T550")]
    public void T550AnnounceAndRrcNamesUseConfiguredSanitationAndColorDepth()
    {
        var announce = new NomadNetAnnounceEntry(1000, new string('a', 32), Convert.ToHexString(Encoding.UTF8.GetBytes("Alice😀")), "node");
        Assert.DoesNotContain("😀", NomadNetAnnounceStream.Label(announce, false, DateTimeOffset.Now));
        Assert.Contains("😀", NomadNetAnnounceStream.Label(announce, false, DateTimeOffset.Now, false));
        var message = new RrcChatMessage("message", "room", new string('a', 32), "Alice😀", "same body", 1000, false);
        var settings = new NomadNetSettings { ColorMode = "monochrome" };
        var clean = NomadNetRrcPresentation.RenderStream(message, settings, new string('b', 32), "me", ansi: true);
        Assert.DoesNotContain("😀", clean);
        Assert.DoesNotContain('\u001b', clean);
        var original = NomadNetRrcPresentation.RenderStream(message, settings with { SanitizeNames = false, ColorMode = "16" },
            new string('b', 32), "me", ansi: true);
        Assert.Contains("😀", original);
        Assert.DoesNotContain("38;2", original);
    }

    private sealed class FailedWriter : StringWriter
    {
        public override Task WriteLineAsync(ReadOnlyMemory<char> buffer, CancellationToken cancellationToken = default) =>
            Task.FromException(new IOException("Synthetic output failure."));
    }
}
